            aOrbiterD = (((aWandererJ + RotL64(aPrevious, 60U)) + RotL64(aCarry, 39U)) + 0xC50A889363CF5A69ULL) + aOASaltG[(((511U - aIndex) + 23U)) & S_SALT1];
