            aOrbiterC = (aOrbiterC + aOrbiterD) + 0xDD67F55ED87EC552ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xD05565DFBE3DE95BULL;
            aOrbiterA = RotL64((aOrbiterA * 0xEDEBDD4B94392D97ULL), 47U);
