            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x66B6FA1BAB250E50ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x302E681716AACD85ULL), 35U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xEE736DEB3214F890ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x68D310C588F73170ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x2459EA05CC35E641ULL), 41U);
