            aIngress = aIngress + RotL64(aOrbiterA, 13U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererG = aWandererG + ((((RotL64(aIngress, 21U) + RotL64(aOrbiterJ, 51U)) + aOrbiterG) + RotL64(aCarry, 35U)) + aWUSaltB[(((511U - aIndex) + 474U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aCross, 5U) + RotL64(aOrbiterE, 43U)) + aOrbiterC) + aWUSaltC[(((511U - aIndex) + 188U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aScatter, 41U) + aOrbiterC) + RotL64(aOrbiterA, 29U)) + RotL64(aCarry, 3U));
            aWandererC = aWandererC ^ ((RotL64(aPrevious, 51U) + aOrbiterE) + RotL64(aOrbiterA, 12U));
            aWandererD = aWandererD + (((RotL64(aScatter, 58U) + RotL64(aOrbiterB, 37U)) + aOrbiterE) + aWUSaltA[(((511U - aIndex) + 249U)) & S_SALT1]);
