            aScatter = (RotL64(aIngress, 40U) + RotL64(aCross, 21U)) ^ (RotL64(aPrevious, 5U) + RotL64(aCarry, 57U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = ((aWandererJ + RotL64(aScatter, 35U)) + 0x79AEE3EB54AAA212ULL) + aOASaltB[(((511U - aIndex) + 386U)) & S_SALT1];
            aOrbiterJ = (((aWandererK + RotL64(aCross, 19U)) + RotL64(aCarry, 27U)) + 0x508EC48B22F4AE14ULL) + aOASaltH[((aIndex + 234U)) & S_SALT1];
            aOrbiterI = (aWandererA + RotL64(aIngress, 13U)) + 0x0A96283078EFAC1AULL;
            aOrbiterH = (aWandererI + RotL64(aPrevious, 44U)) + 0xFBF6681E17C8F425ULL;
            aOrbiterE = ((aWandererF + RotL64(aCross, 29U)) + 0xFAB6310584CD6108ULL) + aOASaltG[(((511U - aIndex) + 498U)) & S_SALT1];
            aOrbiterF = (((aWandererC + RotL64(aIngress, 5U)) + RotL64(aCarry, 57U)) + 0x2E526309A0B7A6FDULL) + aOASaltD[(((511U - aIndex) + 460U)) & S_SALT1];
            aOrbiterB = (((aWandererG + RotL64(aPrevious, 53U)) + RotL64(aCarry, 13U)) + 0xCC4AA7AC0F220304ULL) + aOASaltA[(((511U - aIndex) + 228U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterJ) + 0xB99D7B07324C5E5AULL) + aOUSaltD[(((511U - aIndex) + 195U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterK) ^ 0x093D47A1DF0C29C4ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x4F7C2434EC9ADC11ULL), 27U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0xD06B6E55DD97B98EULL) + aOUSaltG[((aIndex + 223U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterH) ^ 0xB6A8108D72C1AC6AULL) ^ aOUSaltA[((aIndex + 91U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0xC0E5F90865D1DB09ULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xBF4D443CDD2F1633ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterJ) ^ 0x1EB3CFBA2B332D3EULL;
            aOrbiterB = RotL64((aOrbiterB * 0x0CAB36E823335149ULL), 5U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0x1A196757B489DF24ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x40868E20BB943B0CULL;
            aOrbiterK = RotL64((aOrbiterK * 0xCAC4AC7C9EF4C095ULL), 47U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0xCA7BBCB5E21A8998ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xA8BF3F9CD050204FULL;
            aOrbiterE = RotL64((aOrbiterE * 0xA6E48C3E907406D1ULL), 11U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x2481D8FE32FCDE12ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0xE88B472A91DE2CE4ULL) ^ aOUSaltH[(((511U - aIndex) + 351U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x057089DD9136F85DULL), 35U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x82066279BE6F5D44ULL) + aOUSaltE[((aIndex + 201U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0x9CEB27512710D43DULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0xA622DB858DFCAAB1ULL), 53U);
