            //
            aWandererJ = aWandererJ ^ ((RotL64(aIngress, 3U) + RotL64(aOrbiterE, 37U)) + aOrbiterF);
            aWandererG = aWandererG + ((((RotL64(aCross, 11U) + RotL64(aOrbiterJ, 5U)) + aOrbiterK) + RotL64(aCarry, 53U)) + aWUSaltF[(((511U - aIndex) + 25U)) & S_SALT1]);
            aWandererI = aWandererI ^ (((RotL64(aScatter, 57U) + RotL64(aOrbiterI, 29U)) + aOrbiterK) + aWUSaltG[((aIndex + 33U)) & S_SALT1]);
            aWandererF = aWandererF + ((((RotL64(aPrevious, 50U) + aOrbiterK) + RotL64(aOrbiterF, 43U)) + RotL64(aCarry, 3U)) + aWUSaltE[(((511U - aIndex) + 225U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aScatter, 37U) + aOrbiterH) + RotL64(aOrbiterF, 13U)) + aWUSaltD[((aIndex + 274U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aPrevious, 43U) + RotL64(aOrbiterB, 53U)) + aOrbiterH) + aWUSaltH[((aIndex + 259U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aIngress, 19U) + aOrbiterE) + RotL64(aOrbiterK, 22U));
