            aOrbiterH = ((aWandererD + RotL64(aPrevious, 53U)) + 0x70457D2E8DE83565ULL) + aOASaltA[(((511U - aIndex) + 476U)) & S_SALT1];
            aOrbiterE = ((aWandererA + RotL64(aCross, 23U)) + RotL64(aCarry, 13U)) + 0x364D52B207EEB472ULL;
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterD) + 0x1CB48EB9FBCC0E5BULL) + aOUSaltF[((aIndex + 317U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x919E086D86C7BC28ULL;
