            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x89443C88C22BACC2ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x1434D1A395DF5DFBULL) ^ aOUSaltB[(((511U - aIndex) + 318U)) & S_SALT1];
